//! Verification
//!
//! This phase iterates over the [`SIR`][crate::lowering::sir] generated by
//! lowering and attempts to verify the structure of the program, typing, and
//! stack effects.
//!
//! This is done by generating constraint equations for instructions, blocks,
//! and bodies within a stack/type effect algebra (so-called rForsp Stack/Type
//! Algebra, abbreviated to rFST), then solving them to produce a sequence of
//! facts about the program.

mod algebra;
